import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第三册：培养技能 · 综合复习与自测 · 第48–58课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第三册：培养技能 · 综合复习与自测 · 第48–58课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-3/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第36–47课","link":"/life/english/new-concept/book-3/review-part-04"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第59–60课","link":"/life/english/new-concept/book-3/review-part-06"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第36–47课","link":"/life/english/new-concept/book-3/review-part-04"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第59–60课","link":"/life/english/new-concept/book-3/review-part-06"}},"headers":[],"relativePath":"life/english/new-concept/book-3/review-part-05.md","filePath":"life/english/new-concept/book-3/review-part-05.md"}'),n={name:"life/english/new-concept/book-3/review-part-05.md"};function r(l,e,i,h,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-综合复习与自测-·-第48–58课" tabindex="-1">第三册：培养技能 · 综合复习与自测 · 第48–58课 <a class="header-anchor" href="#第三册-培养技能-·-综合复习与自测-·-第48–58课" aria-label="Permalink to &quot;第三册：培养技能 · 综合复习与自测 · 第48–58课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-48-·-地点前置的完全倒装" tabindex="-1">Lesson 48 · 地点前置的完全倒装 <a class="header-anchor" href="#lesson-48-·-地点前置的完全倒装" aria-label="Permalink to &quot;Lesson 48 · 地点前置的完全倒装 {#lesson-48-·-地点前置的完全倒装}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Beyond the empty square stood a row of houses with closed shutters.</p><h3 id="练习-1-47" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-47" aria-label="Permalink to &quot;练习 1 {#练习-1-47}&quot;">​</a></h3><p>还原例句为普通语序。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A row of houses with closed shutters stood beyond the empty square.</p><p><strong>解析：</strong> 把主语移回谓语前，地点置后。</p></details><p><strong>表达迁移：</strong> 用三句描绘一处安静场景，包含一个倒装句并避免臆断。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>At the end of the lane stood an empty bus shelter. No voices came from the nearby houses. We could not tell whether the residents were away or simply indoors.</p><p>倒装建立空间，最后一句主动限制对静默的解释。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-048">回看本课</a></p><h2 id="lesson-49-·-介词加关系代词" tabindex="-1">Lesson 49 · 介词加关系代词 <a class="header-anchor" href="#lesson-49-·-介词加关系代词" aria-label="Permalink to &quot;Lesson 49 · 介词加关系代词 {#lesson-49-·-介词加关系代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The assistant on whom the household relied kept a careful record of every delivery.</p><h3 id="练习-1-48" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-48" aria-label="Permalink to &quot;练习 1 {#练习-1-48}&quot;">​</a></h3><p>把例句的关系从句改为介词留末尾的形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The assistant whom the household relied on kept a careful record of every delivery.</p><p><strong>解析：</strong> on 移到 relied 后，whom 也可省略。</p></details><p><strong>表达迁移：</strong> 用三句说明一位虚构助手的可靠性，给出可观察行为。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The coordinator on whom we rely checks every booking twice. She also explains changes before they affect visitors. Clear communication matters more to us than a flawless appearance.</p><p>具体行动支撑可靠评价，最后一句明确价值标准。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-049">回看本课</a></p><h2 id="lesson-50-·-动词后-ing-与-to-do-的意义" tabindex="-1">Lesson 50 · 动词后 ing 与 to do 的意义 <a class="header-anchor" href="#lesson-50-·-动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;Lesson 50 · 动词后 ing 与 to do 的意义 {#lesson-50-·-动词后-ing-与-to-do-的意义}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I stopped checking messages during study sessions and tried leaving my phone in another room.</p><h3 id="练习-1-49" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-49" aria-label="Permalink to &quot;练习 1 {#练习-1-49}&quot;">​</a></h3><p>翻译：记得关灯。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Remember to turn off the light.</p><p><strong>解析：</strong> 提醒执行尚需完成的动作。</p></details><p><strong>表达迁移：</strong> 用三句写一个可检验的学习习惯计划，包含试验和复盘。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I will read for ten minutes after breakfast. If I keep forgetting, I will try leaving the book beside my cup. At the end of the week, I will count the days I actually read.</p><p>时间触发、环境提示和反馈指标完整，比抽象决心更可执行。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-050">回看本课</a></p><h2 id="lesson-51-·-将来完成时的截止视角" tabindex="-1">Lesson 51 · 将来完成时的截止视角 <a class="header-anchor" href="#lesson-51-·-将来完成时的截止视角" aria-label="Permalink to &quot;Lesson 51 · 将来完成时的截止视角 {#lesson-51-·-将来完成时的截止视角}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If the schedule holds, the team will have tested all three models by Friday.</p><h3 id="练习-1-50" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-50" aria-label="Permalink to &quot;练习 1 {#练习-1-50}&quot;">​</a></h3><p>例句保证任何情况下都能周五完成吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不保证。</p><p><strong>解析：</strong> if the schedule holds 是明确条件。</p></details><p><strong>表达迁移：</strong> 用三句对虚构项目作谨慎预测，包含依据、截止点和不确定因素。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The first two trials took one day each. If the remaining trials follow that pattern, we will have finished by Thursday. Unexpected equipment faults could still change the schedule.</p><p>以观察到的模式作条件预测，再指出模式可能失效的因素。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-051">回看本课</a></p><h2 id="lesson-52-·-名词化与动作还原" tabindex="-1">Lesson 52 · 名词化与动作还原 <a class="header-anchor" href="#lesson-52-·-名词化与动作还原" aria-label="Permalink to &quot;Lesson 52 · 名词化与动作还原 {#lesson-52-·-名词化与动作还原}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The seller called the mixture a premium finish, but the label did not explain its ingredients.</p><h3 id="练习-1-51" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-51" aria-label="Permalink to &quot;练习 1 {#练习-1-51}&quot;">​</a></h3><p>将 The team carried out an inspection of the box 改得更直接。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The team inspected the box.</p><p><strong>解析：</strong> 用动词恢复主要动作并保留已知主语。</p></details><p><strong>表达迁移：</strong> 用三句评价一段虚构商品宣传，区分名称和证据。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The brochure calls the fabric revolutionary. It gives no figures for strength or durability. We should test a sample before accepting the description.</p><p>先准确报告宣传，再指出证据缺口，最后提出验证步骤。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-052">回看本课</a></p><h2 id="lesson-53-·-形式主语与真正主语" tabindex="-1">Lesson 53 · 形式主语与真正主语 <a class="header-anchor" href="#lesson-53-·-形式主语与真正主语" aria-label="Permalink to &quot;Lesson 53 · 形式主语与真正主语 {#lesson-53-·-形式主语与真正主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It is essential that every complaint be recorded before the review begins.</p><h3 id="练习-1-52" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-52" aria-label="Permalink to &quot;练习 1 {#练习-1-52}&quot;">​</a></h3><p>例句中的 be 为什么不是 is？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 它用于 essential 后的建议性原形虚拟式。</p><p><strong>解析：</strong> 也可表达为 should be recorded。</p></details><p><strong>表达迁移：</strong> 用三句设计虚构社区意见渠道，说明记录、回应和结果公开。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It is important that residents know where to send concerns. Each message should receive a reference number. The committee should publish a summary of actions without exposing private details.</p><p>用形式主语提出可操作原则，随后给出具体机制与隐私边界。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-053">回看本课</a></p><h2 id="lesson-54-·-whatever-与-no-matter-what" tabindex="-1">Lesson 54 · whatever 与 no matter what <a class="header-anchor" href="#lesson-54-·-whatever-与-no-matter-what" aria-label="Permalink to &quot;Lesson 54 · whatever 与 no matter what {#lesson-54-·-whatever-与-no-matter-what}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Whatever caused the bird to choose the red lid, one trial cannot establish a general rule.</p><h3 id="练习-1-53" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-53" aria-label="Permalink to &quot;练习 1 {#练习-1-53}&quot;">​</a></h3><p>例句的一次试验能确立规律吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 主句明确否定这一推论。</p></details><p><strong>表达迁移：</strong> 用三句报告虚构动物观察，提出两个解释和后续测试。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The bird opened the red box first. It may have noticed a food smell rather than the colour. We should switch the boxes and repeat the observation.</p><p>观察与假设分开，后续操作针对气味和颜色这两个变量。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-054">回看本课</a></p><h2 id="lesson-55-·-省略-if-的条件倒装" tabindex="-1">Lesson 55 · 省略 if 的条件倒装 <a class="header-anchor" href="#lesson-55-·-省略-if-的条件倒装" aria-label="Permalink to &quot;Lesson 55 · 省略 if 的条件倒装 {#lesson-55-·-省略-if-的条件倒装}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Should anyone detect the signal, the repeated pattern may help them recognize it as intentional.</p><h3 id="练习-1-54" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-54" aria-label="Permalink to &quot;练习 1 {#练习-1-54}&quot;">​</a></h3><p>还原例句的条件倒装。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> If anyone should detect the signal, the repeated pattern may help them recognize it as intentional.</p><p><strong>解析：</strong> 将 should 放回主语后并补 if。</p></details><p><strong>表达迁移：</strong> 用三句设计一条给未知接收者的虚构信息，说明格式与限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We would begin with a short repeated pattern. Should a receiver notice it, the repetition might suggest deliberate design. We cannot assume that the receiver would understand our pictures.</p><p>先描述设计，再给条件性效果，最后承认符号共享前提尚未成立。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-055">回看本课</a></p><h2 id="lesson-56-·-混合时间条件句" tabindex="-1">Lesson 56 · 混合时间条件句 <a class="header-anchor" href="#lesson-56-·-混合时间条件句" aria-label="Permalink to &quot;Lesson 56 · 混合时间条件句 {#lesson-56-·-混合时间条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If we had moved the supplies upstairs yesterday, they would be dry now.</p><h3 id="练习-1-55" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-55" aria-label="Permalink to &quot;练习 1 {#练习-1-55}&quot;">​</a></h3><p>例句的条件发生在何时？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 昨天。</p><p><strong>解析：</strong> yesterday 与 had moved 标明过去。</p></details><p><strong>表达迁移：</strong> 写三句虚构涨水后的复盘，区分过去遗漏、现在影响和下一次准备。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We left the storage boxes on the ground floor. If we had raised them earlier, the contents would be usable now. Before the next rainy season, we will move the shelves upstairs.</p><p>因果链时间明确，未来措施直接对应此前遗漏。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-056">回看本课</a></p><h2 id="lesson-57-·-as-if-与假设语气" tabindex="-1">Lesson 57 · as if 与假设语气 <a class="header-anchor" href="#lesson-57-·-as-if-与假设语气" aria-label="Permalink to &quot;Lesson 57 · as if 与假设语气 {#lesson-57-·-as-if-与假设语气}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The bakery smelled as if nothing had changed since my childhood.</p><h3 id="练习-1-56" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-56" aria-label="Permalink to &quot;练习 1 {#练习-1-56}&quot;">​</a></h3><p>例句直接断言店内所有事物未变吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> as if 将内容限定为感官印象。</p></details><p><strong>表达迁移：</strong> 用三句写回到旧街区的体验，既写熟悉也写变化。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The bread smelled as if I had stepped into my childhood. Outside, the old cinema had become a supermarket. The smell was familiar, but the street no longer matched my memory.</p><p>主观联想与客观变化并列，结论不把记忆当作完整现实。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-057">回看本课</a></p><h2 id="lesson-58-·-but-for-与-without-的隐含条件" tabindex="-1">Lesson 58 · but for 与 without 的隐含条件 <a class="header-anchor" href="#lesson-58-·-but-for-与-without-的隐含条件" aria-label="Permalink to &quot;Lesson 58 · but for 与 without 的隐含条件 {#lesson-58-·-but-for-与-without-的隐含条件}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> But for the dated receipt, we would have been unable to explain the mix-up.</p><h3 id="练习-1-57" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-57" aria-label="Permalink to &quot;练习 1 {#练习-1-57}&quot;">​</a></h3><p>例句收据实际存在吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 存在。</p><p><strong>解析：</strong> 反事实“要不是收据”暗示实际有该证据帮助。</p></details><p><strong>表达迁移：</strong> 写三句小误会的处理过程，包含一项决定性线索。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The clerk thought I had collected the parcel already. But for the tracking message, the mistake would have continued. We checked the reference number and found a second customer with the same surname.</p><p>误解、关键证据和具体核查组成因果链，未仅靠人物情绪推动结局。</p></details><p><a href="/life/english/new-concept/book-3/unit-03/lesson-058">回看本课</a></p>',92)])])}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
